contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 value) public payable {
        require(to != address(0));
        uint256 beforeOwnerBalance = c.balanceOf(msg.sender); if (__ESBMC_reverted()) return;
        uint256 beforeToBalance = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(beforeOwnerBalance >= value);
        require(!c.frozenAccount(msg.sender));
        require(!c.frozenAccount(to));

        c.transfer(to, value); if (__ESBMC_reverted()) return;

        assert(
            c.balanceOf(msg.sender) + value == beforeOwnerBalance &&
            c.balanceOf(to) == beforeToBalance + value &&
            c.balanceOf(msg.sender) + c.balanceOf(to) + (beforeTotalSupply - beforeOwnerBalance - beforeToBalance) == c.totalSupply()
        );
    }

    receive() external payable {}
}

